import base64, fcntl, hashlib, json, os, plistlib, re, shutil, signal, socket, ssl, struct, subprocess, sys, tempfile, time
from concurrent.futures import ThreadPoolExecutor

ADB_PORT = 5037
STATE_DIR = os.path.expanduser("~/Library/Caches/notchany-android-devices")
REMOTE_DIR = "/data/local/tmp"


_labels = None


def T(key, **kw):
    # 详情页规格字段名、剪贴板与 iOS 文案分别打包在 detail_labels / clip_labels / ios_labels 词条里（单个动作最多 64 条词条）
    global _labels
    text = notch_t(key)
    if text == key:
        if _labels is None:
            _labels = {}
            for packed in ("detail_labels", "clip_labels", "ios_labels"):
                try:
                    _labels.update(json.loads(notch_t(packed)))
                except ValueError:
                    pass
        text = _labels.get(key, key)
    return text.format(**kw) if kw else text


def find_adb():
    path = shutil.which("adb")
    if path:
        return path
    for cand in ("~/Library/Android/sdk/platform-tools/adb", "/opt/homebrew/bin/adb", "/usr/local/bin/adb"):
        cand = os.path.expanduser(cand)
        if os.access(cand, os.X_OK):
            return cand
    return None


def server_running():
    try:
        with socket.create_connection(("127.0.0.1", ADB_PORT), timeout=0.5):
            return True
    except OSError:
        return False


def shell(adb, serial, cmd, timeout=10):
    return subprocess.run([adb, "-s", serial, "shell", cmd], capture_output=True, text=True, timeout=timeout)


def transport_of(serial, attrs):
    if serial.startswith("emulator-"):
        return "emulator"
    if "usb" in attrs:
        return "usb"
    if re.match(r"^[\d.]+:\d+$", serial) or "._adb-tls-connect." in serial:
        return "wifi"
    return "other"


def list_devices(adb):
    out = subprocess.run([adb, "devices", "-l"], capture_output=True, text=True, timeout=5).stdout
    devices = []
    for line in out.splitlines()[1:]:
        parts = line.split()
        if len(parts) < 2:
            continue
        serial, state = parts[0], parts[1]
        attrs = dict(p.split(":", 1) for p in parts[2:] if ":" in p)
        devices.append({
            "serial": serial,
            "state": state,
            "model": attrs.get("model", "").replace("_", " "),
            "transport": transport_of(serial, attrs),
        })
    return devices


PROBE = ("getprop ro.product.manufacturer; getprop ro.product.model; "
         "getprop ro.build.version.release; settings get global device_name; dumpsys battery")


def enrich(adb, dev):
    if dev["state"] != "device":
        return dev
    try:
        out = shell(adb, dev["serial"], PROBE, timeout=4).stdout
    except subprocess.TimeoutExpired:
        return dev
    lines = out.splitlines()
    head = (lines + [""] * 4)[:4]
    maker, model, release, name = (s.strip() for s in head)
    if name in ("null", ""):
        name = ""
    dev["maker"] = maker
    dev["model"] = model or dev["model"]
    dev["name"] = name or " ".join(x for x in (maker.capitalize() if maker.islower() else maker, model) if x)
    dev["android"] = release
    batt = {}
    for l in lines[4:]:
        m = re.match(r"^\s{2}(level|status|AC powered|USB powered|Wireless powered):\s*(\S+)", l)
        if m:
            batt[m.group(1)] = m.group(2)
    if "level" in batt:
        dev["battery"] = int(batt["level"])
        dev["charging"] = batt.get("status") in ("2", "5") or any(
            batt.get(k) == "true" for k in ("AC powered", "USB powered", "Wireless powered"))
    return dev


def adb_state(adb):
    return "missing" if not adb else "ok" if server_running() else "stopped"


def snapshot(adb):
    # Android 走 adb，iOS 走 usbmuxd，两边并行；adb 缺失或没启动不影响 iOS 设备显示
    state = adb_state(adb)
    with ThreadPoolExecutor(max_workers=8) as pool:
        ios = pool.submit(ios_devices)
        devices = list_devices(adb) if state == "ok" else []
        devices = list(pool.map(lambda d: enrich(adb, d), devices))
        for d in devices:
            if d.get("android"):
                d["os"] = "Android " + d["android"]
        connected = {d["serial"] for d in devices if d["state"] == "device"}
        devices += ios.result()
    active, notes = reconcile(adb, connected)
    for d in devices:
        rec = active.get(d["serial"])
        if rec:
            d["recording"] = {"started_at": rec["started_at"], "limit": rec["limit"]}
    order = {"device": 0, "unauthorized": 1, "untrusted": 1}
    devices.sort(key=lambda d: (order.get(d["state"], 2), d.get("name") or d["model"] or d["serial"]))
    return {"status": "ok", "adb": state, "devices": devices}, notes


def output_dir():
    chosen = os.environ.get("NOTCH_PARAM_SAVE_DIR", "").strip()
    if chosen:
        path = os.path.expanduser(chosen)
    elif os.environ.get("NOTCH_OUTPUT_DIR"):
        path = os.environ["NOTCH_OUTPUT_DIR"]
    else:
        # 跟随 Mac 自己的截图位置（系统设置 / ⇧⌘5 里改的那个），没设过就是桌面
        path = os.path.expanduser("~/Desktop")
        try:
            loc = subprocess.run(["defaults", "read", "com.apple.screencapture", "location"],
                                 capture_output=True, text=True, timeout=2).stdout.strip()
            if loc and os.path.isdir(os.path.expanduser(loc)):
                path = os.path.expanduser(loc)
        except (OSError, subprocess.TimeoutExpired):
            pass
    if not os.path.isdir(path):
        sys.exit(T("err_dir_missing", path=path))
    return path


def unique_path(base, ext):
    out_dir = output_dir()
    base = re.sub(r"[/:\\]+", "-", base).strip() or "Android"
    path = os.path.join(out_dir, base + ext)
    n = 2
    while os.path.exists(path):
        path = os.path.join(out_dir, f"{base} {n}{ext}")
        n += 1
    return path


def take_screenshot(adb, serial, label):
    path = unique_path(f"{label} {time.strftime('%Y-%m-%d %H.%M.%S')}", ".png")
    tmp = os.path.join(os.environ.get("NOTCH_TEMP_DIR") or os.path.dirname(path), ".android-screencap.png")
    try:
        with open(tmp, "wb") as f:
            r = subprocess.run([adb, "-s", serial, "exec-out", "screencap", "-p"],
                               stdout=f, stderr=subprocess.PIPE, timeout=20)
    except subprocess.TimeoutExpired:
        sys.exit(T("err_shot_timeout", name=label))
    with open(tmp, "rb") as f:
        valid = f.read(8) == b"\x89PNG\r\n\x1a\n"
    if r.returncode != 0 or not valid:
        os.remove(tmp)
        err = r.stderr.decode(errors="replace").strip()
        sys.exit(T("err_shot_failed", name=label) + (" · " + err if err else ""))
    shutil.move(tmp, path)
    return path


# ---- 录屏：screenrecord 在手机端 nohup 后台跑，Mac 侧只记一份状态文件 ----

def rec_file(serial):
    return os.path.join(STATE_DIR, "rec-" + re.sub(r"[^A-Za-z0-9._-]", "_", serial) + ".json")


def load_recordings():
    recs = []
    if os.path.isdir(STATE_DIR):
        for name in sorted(os.listdir(STATE_DIR)):
            if name.startswith("rec-") and name.endswith(".json"):
                try:
                    with open(os.path.join(STATE_DIR, name)) as f:
                        recs.append(json.load(f))
                except (OSError, ValueError):
                    pass
    return recs


def lock(serial, block):
    # 停止与后台自动保存可能并发，同一设备的拉取用文件锁串行
    os.makedirs(STATE_DIR, exist_ok=True)
    fd = open(rec_file(serial) + ".lock", "w")
    try:
        fcntl.flock(fd, fcntl.LOCK_EX | (0 if block else fcntl.LOCK_NB))
    except BlockingIOError:
        fd.close()
        return None
    return fd


def recorder_alive(adb, rec):
    if rec.get("platform") == "ios":
        return ios_recorder_alive(rec)
    cmd = f'[ "$(cat /proc/{rec["pid"]}/comm 2>/dev/null)" = screenrecord ] && echo y'
    return shell(adb, rec["serial"], cmd, timeout=5).stdout.strip() == "y"


def start_recording(adb, serial, label):
    if os.path.exists(rec_file(serial)):
        sys.exit(T("err_rec_busy", name=label))
    try:
        minutes = float(os.environ.get("NOTCH_PARAM_RECORD_MAX_MINUTES") or 30)
    except ValueError:
        minutes = 30
    limit = max(60, int(minutes * 60))
    started = int(time.time() * 1000)
    remote = f"{REMOTE_DIR}/notchany-rec-{started}.mp4"
    log = remote[:-4] + ".log"
    # 旧系统 screenrecord 最长 180 秒；help 里写了 "Set to 0" 的版本才不设上限
    cmd = (f'if screenrecord --help 2>&1 | grep -q "Set to 0"; then lim={limit}; else lim={min(limit, 180)}; fi; '
           f'nohup screenrecord --bit-rate 8000000 --time-limit $lim {remote} >{log} 2>&1 & echo $! $lim')
    out = shell(adb, serial, cmd).stdout.split()
    if len(out) < 2 or not out[0].isdigit():
        sys.exit(T("err_rec_start", name=label))
    rec = {"serial": serial, "label": label, "pid": int(out[0]), "limit": int(out[1]),
           "remote": remote, "log": log, "started_at": started}
    time.sleep(0.6)
    if not recorder_alive(adb, rec):
        err = shell(adb, serial, f"cat {log}; rm -f {remote} {log}").stdout.strip()
        sys.exit(T("err_rec_start", name=label) + (" · " + err.splitlines()[-1] if err else ""))
    os.makedirs(STATE_DIR, exist_ok=True)
    with open(rec_file(serial), "w") as f:
        json.dump(rec, f)
    return rec


def save_recording(adb, rec, stop):
    """停止（可选）并把录屏拉回 Mac，返回保存路径。调用方需持有该设备的锁。"""
    serial, label = rec["serial"], rec["label"]
    if rec.get("platform") == "ios":
        return ios_save_recording(rec, stop)
    if stop:
        shell(adb, serial, f"kill -INT {rec['pid']}", timeout=5)
    deadline = time.time() + 15
    while recorder_alive(adb, rec):
        if time.time() > deadline:
            sys.exit(T("err_rec_stuck", name=label))
        time.sleep(0.3)
    stamp = time.strftime("%Y-%m-%d %H.%M.%S", time.localtime(rec["started_at"] / 1000))
    path = unique_path(f"{label} {stamp}", ".mp4")
    tmp = os.path.join(os.environ.get("NOTCH_TEMP_DIR") or os.path.dirname(path), ".android-screenrecord.mp4")
    r = subprocess.run([adb, "-s", serial, "pull", rec["remote"], tmp], capture_output=True, text=True, timeout=540)
    if r.returncode != 0 or not os.path.exists(tmp):
        if shell(adb, serial, f"[ -e {rec['remote']} ] || echo gone").stdout.strip() == "gone":
            os.remove(rec_file(serial))
            sys.exit(T("err_rec_gone", name=label))
        sys.exit(T("err_rec_pull", name=label) + " · " + (r.stderr.strip() or r.stdout.strip()))
    shutil.move(tmp, path)
    shell(adb, serial, f"rm -f {rec['remote']} {rec['log']}")
    os.remove(rec_file(serial))
    return path


def ongoing_note(rec, online, failed=False):
    since = time.strftime("%H:%M", time.localtime(rec["started_at"] / 1000))
    if not online:
        details = T("rec_disconnected")
    elif failed:
        details = T("rec_save_failed")
    else:
        details = T("rec_since", time=since, minutes=rec["limit"] // 60)
    return {
        "id": "rec-" + rec["serial"], "type": "ongoing",
        "activation_id": f"{rec['serial']}:{rec['started_at']}",
        "icon": {"symbol": "record.circle"}, "accent_hex": "#FF453A",
        "title": T("rec_title", name=rec["label"]), "details": details, "status": "running",
        "actions": [{"id": "stop", "symbol": "stop.fill", "label": T("rec_stop_save"), "invoke": "record-stop",
                     "payload": {"serial": rec["serial"], "platform": rec.get("platform", "android"),
                                 "via": "notification"}}],
    }


def saved_note(rec, path):
    return {"id": f"rec-saved-{rec['serial']}-{rec['started_at']}", "type": "event", "status": "done",
            "icon": {"symbol": "video"}, "title": T("rec_saved"),
            "details": os.path.basename(path), "on_click": {"open": path}}


def reconcile(adb, connected):
    """进行中的录屏重申持续通知；已自行结束（到达时长上限）的自动拉回并发「已保存」事件。"""
    active, notes = {}, []
    for rec in load_recordings():
        serial = rec["serial"]
        # iOS 录屏进程跑在 Mac 上：手机拔出时它会自行收尾退出，按「已结束」处理
        online = rec.get("platform") == "ios" or serial in connected
        failed = False
        if online and not recorder_alive(adb, rec):
            fd = lock(serial, block=False)
            if fd is None:  # 另一次运行正在保存
                continue
            try:
                if not os.path.exists(rec_file(serial)):
                    continue
                path = save_recording(adb, rec, stop=False)
                notes += [{"end": "rec-" + serial}, saved_note(rec, path)]
                continue
            except SystemExit:
                if not os.path.exists(rec_file(serial)):
                    notes.append({"end": "rec-" + serial})
                    continue
                failed = True
            finally:
                fd.close()
        active[serial] = rec
        notes.append(ongoing_note(rec, online, failed))
    return active, notes


