    rows = []
    design = int(psy["charge_full_design"]) // 1000 if psy.get("charge_full_design", "").isdigit() else \
        int(batt["design capacity"]) // 1000 if batt.get("design capacity", "").isdigit() else None
    full = int(psy["charge_full"]) // 1000 if psy.get("charge_full", "").isdigit() else \
        int(batt["maximum capacity"]) // 1000 if batt.get("maximum capacity", "").isdigit() else None
    if not design:
        try:
            cap = shell(adb, serial, "dumpsys batterystats 2>/dev/null | grep -m1 -E '^ +Capacity: '", timeout=10).stdout
            m = re.search(r"Typical: (\d+)", cap) or re.search(r"Capacity: (\d+)", cap)
