        rows.append([T("row_capacity"), text])
    if psy.get("cycle_count", "").isdigit():
        rows.append([T("row_cycles"), T("cycles_value", n=psy["cycle_count"])])
    if batt.get("health"):
        health = T("health_" + batt["health"]) if batt["health"] in ("2", "3", "4", "5", "6", "7") else batt["health"]
        rows.append([T("row_health"), health + (" · " + batt["technology"] if batt.get("technology") else "")])
    sections.append({"title": T("sec_battery"), "rows": rows})

    rows = []
    sdk = p("ro.build.version.sdk", "")
    rows.append(["Android", T("android_api", release=p("ro.build.version.release", ""), sdk=sdk)])
    if p("ro.build.version.security_patch"):
        rows.append([T("row_patch"), p("ro.build.version.security_patch")])
    if p("ro.build.display.id"):
        rows.append([T("row_build"), p("ro.build.display.id")])
    if s.get("uname"):
        rows.append([T("row_kernel"), s["uname"][0].strip()])
    if p("gsm.version.baseband"):
        rows.append([T("row_baseband"), p("gsm.version.baseband").split(",")[0]])
    first = p("ro.product.first_api_level", "")
    if first.isdigit():
        rows.append([T("row_first_os"), f"Android {ANDROID_OF_API.get(int(first), first)}"])
    tags = [x for x, ok in ((T("feat_ab"), p("ro.build.ab_update") == "true"), ("Treble", p("ro.treble.enabled") == "true")) if ok]
    if s.get("selinux") and s["selinux"][0].strip():
        tags.append("SELinux " + s["selinux"][0].strip())
    if tags:
        rows.append([T("row_features"), " · ".join(tags)])
    if s.get("uptime"):
        up = int(float(s["uptime"][0].split()[0]))
        d, h, mi = up // 86400, up % 86400 // 3600, up % 3600 // 60
        rows.append([T("row_uptime"), (T("uptime_days", d=d) if d else "") + T("uptime_hm", h=h, m=mi)])
    sections.append({"title": T("sec_system"), "rows": rows})

    rows = []
    name = s.get("name", ["null"])[0].strip()
    rows.append([T("row_name"), name if name and name != "null" else p("ro.product.model", "")])
    rows.append([T("row_model"), " · ".join(x for x in (p("ro.product.manufacturer"), p("ro.product.model"), p("ro.product.device")) if x)])
    rows.append([T("row_serial"), serial])
    ip = re.search(r"inet ([\d.]+)", "\n".join(s.get("net", [])))
    if ip:
        rows.append(["Wi‑Fi IP", ip.group(1)])
    hw = [n for f, n in (("android.hardware.nfc", "NFC"), ("android.hardware.fingerprint", T("hw_fingerprint")),
                         ("android.hardware.biometrics.face", T("hw_face")), ("android.hardware.consumerir", T("hw_ir")),
                         ("android.hardware.telephony.euicc", "eSIM"), ("android.hardware.uwb", "UWB")) if f in features]
    if hw:
        rows.append([T("row_hw"), " · ".join(hw)])
    sections.append({"title": T("sec_device"), "rows": rows})

    return [sec for sec in sections if sec["rows"]]


def collect_live(adb, serial):
    s = run_sections(adb, serial, LIVE_CMD, timeout=10)
    live = {}
    stat = s.get("stat", [""])[0].split()
    if len(stat) > 5 and stat[0] == "cpu":
        nums = [int(x) for x in stat[1:]]
        total, idle = sum(nums[:8]), nums[3] + nums[4]
        cache = os.path.join(STATE_DIR, "stat-" + re.sub(r"[^A-Za-z0-9._-]", "_", serial) + ".json")
        prev = None
        try:
            with open(cache) as f:
                prev = json.load(f)
        except (OSError, ValueError):
            pass
        if not prev or time.time() - prev["t"] > 15 or total <= prev["total"]:
            # 距上次采样太久：就地补采一个短样本，不拿开机以来的均值冒充当前占用
            prev = {"total": total, "idle": idle}
            time.sleep(0.4)
            again = shell(adb, serial, "head -1 /proc/stat", timeout=5).stdout.split()
            nums = [int(x) for x in again[1:]]
            total, idle = sum(nums[:8]), nums[3] + nums[4]
        if total > prev["total"]:
            live["cpu_usage"] = round(100 * (1 - (idle - prev["idle"]) / (total - prev["total"])), 1)
        os.makedirs(STATE_DIR, exist_ok=True)
        with open(cache, "w") as f:
            json.dump({"t": time.time(), "total": total, "idle": idle}, f)
    freqs = [int(l.split()[1]) for l in s.get("cur", []) if len(l.split()) > 1 and l.split()[1].isdigit()]
    if freqs:
        live["cpu_freq_mhz"] = max(freqs) // 1000
    mem = {k: int(v.split()[0]) for k, v in kv_lines(s.get("mem", [])).items() if v.split()}
    if mem.get("memtotal"):
        live["mem_total_kb"], live["mem_avail_kb"] = mem["memtotal"], mem.get("memavailable", 0)
    temps = {}
    for l in s.get("thermal", []):
        m = re.search(r"mValue=([\d.-]+), mType=(-?\d+), mName=([^,]+)", l)
        if m and float(m.group(1)) > 0:
            temps.setdefault(int(m.group(2)), []).append(float(m.group(1)))
    for typ, key in ((0, "cpu_temp"), (1, "gpu_temp"), (3, "skin_temp")):
        if temps.get(typ):
            live[key] = round(max(temps[typ]), 1)
    batt = kv_lines(s.get("battery", []))
    if batt.get("level", "").isdigit():
        live["battery"] = int(batt["level"])
        live["charging"] = batt.get("status") in ("2", "5") or any(
            batt.get(k) == "true" for k in ("ac powered", "usb powered", "wireless powered"))
    if batt.get("temperature", "").lstrip("-").isdigit():
        live["battery_temp"] = int(batt["temperature"]) / 10
    if batt.get("voltage", "").isdigit():
        v = int(batt["voltage"])
        live["battery_volt"] = round(v / 1000 if v > 100 else v, 2)
    gpu = re.match(r"(\d+)", (s.get("gpu") or [""])[0].strip())
    if gpu:
        live["gpu_busy"] = int(gpu.group(1))
    return live


# ---- 剪贴板：Android 没有读写剪贴板的 shell 命令，推一个小 dex 以 shell 身份经 app_process 调系统剪贴板服务 ----
# 源码见 NotchClip.java（反射调 IClipboard.getPrimaryClip/setPrimaryClip，锁屏时报 LOCKED），d8 --min-api 21 编译

CLIP_DEX = ""


def clip_helper(adb, serial, label, cmd, data=""):
    dex = base64.b64decode(CLIP_DEX)
    name = "notchany-clip-%s.dex" % hashlib.sha256(dex).hexdigest()[:12]
    remote = REMOTE_DIR + "/" + name
    command = f"[ -f {remote} ] || {{ echo MISSING; exit; }}; CLASSPATH={remote} app_process / NotchClip {cmd}"
    for attempt in range(2):
        try:
            r = subprocess.run([adb, "-s", serial, "shell", command], input=data, capture_output=True, text=True, timeout=20)
        except subprocess.TimeoutExpired:
            sys.exit(T("clip_failed", name=label) + " · timeout")
        lines = r.stdout.strip().splitlines()
        reply = next((l for l in reversed(lines) if l.split(" ", 1)[0] in ("OK", "EMPTY", "NONTEXT", "LOCKED", "ERR", "MISSING")), "")
        if reply != "MISSING" or attempt:
            break
        # 首次使用或助手升级：清掉旧版本再推送（文件名带内容哈希）
        local = os.path.join(STATE_DIR, name)
        if not os.path.exists(local):
            os.makedirs(STATE_DIR, exist_ok=True)
            with open(local + ".tmp", "wb") as f:
                f.write(dex)
            os.replace(local + ".tmp", local)
        subprocess.run([adb, "-s", serial, "shell", f"rm -f {REMOTE_DIR}/notchany-clip-*.dex"], capture_output=True, timeout=10)
        p = subprocess.run([adb, "-s", serial, "push", local, remote], capture_output=True, text=True, timeout=20)
        if p.returncode != 0:
            sys.exit(T("clip_failed", name=label) + " · " + (p.stderr.strip() or p.stdout.strip()))
    if reply.startswith("ERR "):
        err = reply[4:]
    elif reply in ("", "MISSING"):
        out = (r.stderr.strip() or r.stdout.strip()).splitlines()
        err = out[-1] if out else ""
    else:
        return reply
    sys.exit(T("clip_failed", name=label) + (" · " + err if err else ""))


