def recvn(sock, n):
    buf = b""
    while len(buf) < n:
        chunk = sock.recv(n - len(buf))
        if not chunk:
            raise ConnectionError("closed")
        buf += chunk
    return buf


def mux_open(timeout=4):
    sock = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)
    sock.settimeout(timeout)
    sock.connect(MUX_SOCK)
    return sock


def mux_request(sock, msg):
    body = plistlib.dumps({"ClientVersionString": "notchany", "ProgName": "notchany", "kLibUSBMuxVersion": 3, **msg})
    sock.sendall(struct.pack("<IIII", 16 + len(body), 1, 8, 1) + body)
    size = struct.unpack("<IIII", recvn(sock, 16))[0]
    return plistlib.loads(recvn(sock, size - 16))


def mux_once(msg):
    sock = mux_open()
    try:
        return mux_request(sock, msg)
    finally:
        sock.close()


def ios_usb():
    """USB 连接的 iOS 设备 {udid: usbmuxd DeviceID}；同一台设备的 Wi‑Fi 连接不算。"""
    try:
        reply = mux_once({"MessageType": "ListDevices"})
    except (OSError, ValueError, plistlib.InvalidFileException, struct.error):
        return {}
    return {d["Properties"]["SerialNumber"]: d["DeviceID"] for d in reply.get("DeviceList", [])
            if d.get("Properties", {}).get("ConnectionType") == "USB" and d["Properties"].get("SerialNumber")}


class Plist:
    """lockdownd 及其服务的 4 字节大端长度 + plist 报文。"""

    def __init__(self, sock):
        self.sock = sock

    def req(self, msg):
        body = plistlib.dumps(msg)
        self.sock.sendall(struct.pack(">I", len(body)) + body)
        return plistlib.loads(recvn(self.sock, struct.unpack(">I", recvn(self.sock, 4))[0]))

    def close(self):
        try:
            self.sock.close()
        except OSError:
            pass


class Lockdown(Plist):
    def __init__(self, devid, udid):
        self.devid, self.udid, self.ctx = devid, udid, None
        super().__init__(self.connect(LOCKDOWN_PORT))

    def __enter__(self):
        return self

    def __exit__(self, *exc):
        self.close()

    def connect(self, port):
        sock = mux_open()
        reply = mux_request(sock, {"MessageType": "Connect", "DeviceID": self.devid, "PortNumber": socket.htons(port)})
        if reply.get("Number") != 0:
            sock.close()
            raise ConnectionError(f"usbmuxd connect {port}: {reply.get('Number')}")
        return sock

    def value(self, domain=None, key=None):
        msg = {"Request": "GetValue", "Label": "notchany"}
        if domain:
            msg["Domain"] = domain
        if key:
            msg["Key"] = key
        reply = self.req(msg)
        return reply.get("Value") if "Error" not in reply else None

    def start_session(self):
        """返回 None 表示会话已建立；否则返回 untrusted 或错误码。"""
        try:
            record = mux_once({"MessageType": "ReadPairRecord", "PairRecordID": self.udid}).get("PairRecordData")
        except OSError:
            record = None
        if not record:
            return "untrusted"
        record = plistlib.loads(record)
        reply = self.req({"Request": "StartSession", "Label": "notchany",
                          "HostID": record["HostID"], "SystemBUID": record["SystemBUID"]})
        if "Error" in reply:
            return "untrusted" if reply["Error"] in ("InvalidHostID", "PairingProhibitedOverThisConnection") else reply["Error"]
        self.ctx = tls_context(record)
        if reply.get("EnableSessionSSL"):
            self.sock = self.ctx.wrap_socket(self.sock)
        return None

    def service(self, name):
        reply = self.req({"Request": "StartService", "Label": "notchany", "Service": name})
        if "Port" not in reply:
            raise ConnectionError(f"{name}: {reply.get('Error')}")
        sock = self.connect(reply["Port"])
        return Plist(self.ctx.wrap_socket(sock) if reply.get("EnableServiceSSL") else sock)


def tls_context(record):
    ctx = ssl.SSLContext(ssl.PROTOCOL_TLS_CLIENT)
    ctx.check_hostname = False
    ctx.verify_mode = ssl.CERT_NONE
    for ciphers in ("ALL:!aNULL:!eNULL:@SECLEVEL=0", "ALL:!aNULL:!eNULL"):
        try:
            ctx.set_ciphers(ciphers)
            break
        except ssl.SSLError:
            pass
    # ssl 只能从文件加载证书：写进本次执行独占的 0700 临时目录，加载完立即删除
    folder = tempfile.mkdtemp(dir=os.environ.get("NOTCH_TEMP_DIR") or None)
    cert, key = os.path.join(folder, "host.pem"), os.path.join(folder, "host.key")
    try:
        with open(cert, "wb") as f:
            f.write(record["HostCertificate"])
        with open(os.open(key, os.O_WRONLY | os.O_CREAT, 0o600), "wb") as f:
            f.write(record["HostPrivateKey"])
        ctx.load_cert_chain(cert, key)
    finally:
        shutil.rmtree(folder, ignore_errors=True)
    return ctx


def ios_os_name(info):
    ver = info.get("ProductVersion", "")
    ipad = info.get("DeviceClass") == "iPad" or info.get("ProductType", "").startswith("iPad")
    major = int(ver.split(".")[0]) if ver.split(".")[0].isdigit() else 0
    return ("iPadOS" if ipad and major >= 13 else "iOS") + (" " + ver if ver else "")


def ios_model(info):
    ptype = info.get("ProductType", "")
    return IOS_MODELS.get(ptype, (None,))[0] or ptype or info.get("DeviceClass", "iOS")


def ios_probe(udid, devid):
    try:
        with Lockdown(devid, udid) as ld:
            info = ld.value() or {}
            dev = {"serial": udid, "platform": "ios", "transport": "usb", "state": "device",
                   "name": info.get("DeviceName", ""), "model": ios_model(info), "os": ios_os_name(info)}
            err = ld.start_session()
            if err:
                dev["state"] = err
                return dev
            batt = ld.value("com.apple.mobile.battery") or {}
    except (OSError, ValueError, KeyError, plistlib.InvalidFileException, struct.error):
        return None
    if isinstance(batt.get("BatteryCurrentCapacity"), int):
        dev["battery"] = batt["BatteryCurrentCapacity"]
        dev["charging"] = bool(batt.get("BatteryIsCharging") or batt.get("ExternalConnected"))
    return dev


def ios_devices():
    usb = ios_usb()
    with ThreadPoolExecutor(max_workers=4) as pool:
        found = [d for d in pool.map(lambda kv: ios_probe(*kv), usb.items()) if d]
    try:
        with open(IOS_SEEN) as f:
            seen = json.load(f)
    except (OSError, ValueError):
        seen = {}
    now, ids = time.time(), {d["serial"] for d in found}
    seen = {u: s for u, s in seen.items() if now - s["t"] < IOS_GRACE and u not in ids}
    stale = [s["dev"] for s in seen.values()]
    seen.update({d["serial"]: {"t": now, "dev": d} for d in found})
    found += stale
    os.makedirs(STATE_DIR, exist_ok=True)
    with open(IOS_SEEN + ".tmp", "w") as f:
        json.dump(seen, f)
    os.replace(IOS_SEEN + ".tmp", IOS_SEEN)
    return found


def ios_session(udid, label):
    devid = ios_usb().get(udid)
    if devid is None:
        sys.exit(T("disconnected"))
    ld = Lockdown(devid, udid)
    err = ld.start_session()
    if err:
        ld.close()
        sys.exit(T("ios_untrusted_err", name=label) if err == "untrusted" else T("err_info_failed", name=err))
    return ld


def signed(n):
    return n - (1 << 64) if isinstance(n, int) and n >= 1 << 63 else n


def ios_battery(ld):
    relay = ld.service("com.apple.mobile.diagnostics_relay")
    try:
        reply = relay.req({"Request": "IORegistry", "EntryClass": "AppleSmartBattery"})
        relay.req({"Request": "Goodbye"})
    finally:
        relay.close()
    return (reply.get("Diagnostics") or {}).get("IORegistry") or {}


def ios_live(batt, disk):
    live = {"platform": "ios"}
    data = batt.get("BatteryData") or {}
    if isinstance(batt.get("CurrentCapacity"), int):
        live["battery"] = batt["CurrentCapacity"]
        live["charging"] = bool(batt.get("IsCharging") or batt.get("ExternalConnected"))
    volt = batt.get("Voltage") or batt.get("AppleRawBatteryVoltage")
    if volt:
        live["battery_volt"] = round(volt / 1000, 2)
    amps = signed(batt.get("InstantAmperage", batt.get("Amperage")))
    if isinstance(amps, int):
        live["current_ma"] = amps
        if volt:
            live["power_w"] = round(volt * amps / 1e6, 2)
    if isinstance(batt.get("Temperature"), int):
        live["battery_temp"] = batt["Temperature"] / 100
    design = data.get("DesignCapacity") or batt.get("DesignCapacity")
    full = batt.get("NominalChargeCapacity") or data.get("NominalChargeCapacity") or batt.get("AppleRawMaxCapacity")
    if design and full:
        live["health"] = round(100 * full / design, 1)
    if isinstance(batt.get("CycleCount"), int):
        live["cycles"] = batt["CycleCount"]
    if disk.get("TotalDiskCapacity") and disk.get("AmountDataAvailable") is not None:
        live["storage_total"], live["storage_free"] = disk["TotalDiskCapacity"], disk["AmountDataAvailable"]
    return live


def gb_dec(n):
    # iOS 设置里的存储按十进制 GB 计
    g = n / 1e9
    return f"{g:.1f} GB" if g < 100 else f"{g:.0f} GB"


def ios_sections(udid, info, itunes, batt, disk):
    ptype = info.get("ProductType", "")
    model, chip, ram = IOS_MODELS.get(ptype, (None, None, None))
    platform = (info.get("HardwarePlatform") or "").lower()
    chip = chip or IOS_PLATFORMS.get(platform)
    sections = []

    rows = []
    if chip or platform:
        rows.append([T("row_model"), (chip or platform) + (f"\n{platform}" if chip and platform else "")])
    spec = CHIP_SPECS.get(chip)
    arch = info.get("CPUArchitecture", "")
    if spec:
        rows.append([T("row_cores"), " · ".join(x for x in (T("cores_pe", n=spec[0] + spec[1], p=spec[0], e=spec[1]), arch) if x)])
        rows.append([T("row_process"), f"{spec[2]} nm"])
    elif arch:
        rows.append([T("row_cores"), arch])
    sections.append({"title": T("sec_cpu"), "rows": rows})

    rows = []
    if ram:
        rows.append([T("row_ram"), f"{ram} GB"])
    total, free = disk.get("TotalDiskCapacity"), disk.get("AmountDataAvailable")
    if total:
        cap = round_up(total / 1e9, [16, 32, 64, 128, 256, 512, 1024, 2048])
        text = f"{cap} GB" if cap < 1024 else f"{cap // 1024} TB"
        if free is not None:
            text += "\n" + T("storage_usage", used=gb_dec(total - free), free=gb_dec(free))
        rows.append([T("row_storage"), text])
    sections.append({"title": T("sec_mem"), "rows": rows})

    rows = []
    w, h, scale = itunes.get("ScreenWidth"), itunes.get("ScreenHeight"), itunes.get("ScreenScaleFactor")
    if w and h:
        rows.append([T("row_resolution"), f"{w}×{h}" + (f" · @{scale:g}x" if scale else "")])
    sections.append({"title": T("sec_display"), "rows": rows})

    rows = []
    data = batt.get("BatteryData") or {}
    design = data.get("DesignCapacity") or batt.get("DesignCapacity")
    full = batt.get("NominalChargeCapacity") or data.get("NominalChargeCapacity") or batt.get("AppleRawMaxCapacity")
    if design:
        text = f"{design} mAh"
        if full and full != design:
            text += "\n" + T("capacity_full", full=full, pct=f"{full * 100 / design:.0f}")
        rows.append([T("row_capacity"), text])
    if isinstance(batt.get("CycleCount"), int):
        rows.append([T("row_cycles"), T("cycles_value", n=batt["CycleCount"])])
    adapter = batt.get("AdapterDetails") or {}
    if batt.get("ExternalConnected") and adapter.get("Watts"):
        rows.append([T("row_charger"), " · ".join(x for x in (f"{adapter['Watts']} W", adapter.get("Description", "")) if x)])
    sections.append({"title": T("sec_battery"), "rows": rows})

    rows = [[ios_os_name(info).split(" ")[0], " ".join(x for x in (info.get("ProductVersion"), f"({info['BuildVersion']})" if info.get("BuildVersion") else "") if x)]]
    if info.get("BasebandVersion"):
        rows.append([T("row_baseband"), info["BasebandVersion"]])
    if info.get("FirmwareVersion"):
        rows.append([T("row_firmware"), info["FirmwareVersion"]])
    sections.append({"title": T("sec_system"), "rows": rows})

    rows = [[T("row_name"), info.get("DeviceName", "")],
            [T("row_model"), " · ".join(x for x in (model, ptype, info.get("HardwareModel")) if x)]]
    if info.get("ModelNumber"):
        rows.append([T("row_part"), info["ModelNumber"] + info.get("RegionInfo", "")])
    if info.get("SerialNumber"):
        rows.append([T("row_serial"), info["SerialNumber"]])
    rows.append(["UDID", udid])
    if info.get("WiFiAddress"):
        rows.append(["Wi‑Fi", info["WiFiAddress"]])
    if info.get("BluetoothAddress"):
        rows.append([T("row_bt"), info["BluetoothAddress"]])
    sections.append({"title": T("sec_device"), "rows": rows})
    return [sec for sec in sections if sec["rows"]]


def ios_detail(udid, label, live_only=False):
    try:
        with ios_session(udid, label) as ld:
            batt = ios_battery(ld)
            disk = ld.value("com.apple.disk_usage") or {}
            live = ios_live(batt, disk)
            if live_only:
                return None, live
            info = ld.value() or {}
            itunes = ld.value("com.apple.mobile.iTunes") or {}
    except (OSError, ValueError, plistlib.InvalidFileException, struct.error) as e:
        sys.exit(T("err_info_failed", name=label) + f" · {e}")
    return ios_sections(udid, info, itunes, batt, disk), live


def ios_device_name(udid):
    devid = ios_usb().get(udid)
    if devid is None:
        return None
    try:
        with Lockdown(devid, udid) as ld:
            return ld.value(key="DeviceName")
    except (OSError, ValueError, plistlib.InvalidFileException, struct.error):
        return None


# 屏幕采集：与 QuickTime 相同，经 CoreMediaIO 把 iOS 设备屏幕当作采集设备打开（截帧 / 录 .mov，含手机声音）。
# 首次使用时用本机 swiftc（Xcode 命令行工具）编译下面的源码并缓存，文件名带源码哈希。
# macOS 把 iOS 屏幕当摄像头管控，而 NotchAny 本身没有摄像头权限声明，由它拉起的进程会被静默拒绝（会话照跑、没有画面）：
# 助手内嵌 Info.plist，并以「放弃归属」方式重新拉起自己，让摄像头权限记在助手名下，首次使用由系统弹窗询问

SCREEN_SWIFT = r'''
import AVFoundation
import CoreImage
import CoreMediaIO
import Foundation

setvbuf(stdout, nil, _IOLBF, 0)
let args = CommandLine.arguments
func fail(_ code: String, _ status: Int32) -> Never { print("ERR " + code); exit(status) }
guard args.count >= 4, ["shot", "record"].contains(args[1]) else { fail("usage", 64) }
let mode = args[1], name = args[2], out = URL(fileURLWithPath: args[3])

// 以 responsibility disclaim 重新拉起自己：子进程成为自己的「责任进程」，摄像头权限按助手自身（内嵌 Info.plist）判定。
// 父进程只转发停止信号并透传退出码；子进程仍在同一进程组，NotchAny 清理进程组时一并结束
typealias DisclaimFn = @convention(c) (UnsafeMutablePointer<posix_spawnattr_t?>, Int32) -> Int32
if getenv("NOTCH_SCREEN_CHILD") == nil, let exe = Bundle.main.executablePath,
   let sym = dlsym(UnsafeMutableRawPointer(bitPattern: -2), "responsibility_spawnattrs_setdisclaim") {
  var attr: posix_spawnattr_t? = nil
  posix_spawnattr_init(&attr)
  _ = unsafeBitCast(sym, to: DisclaimFn.self)(&attr, 1)
  setenv("NOTCH_SCREEN_CHILD", "1", 1)
  var child: pid_t = 0
  if posix_spawn(&child, exe, nil, &attr, CommandLine.unsafeArgv, environ) == 0 {
    var relays: [DispatchSourceSignal] = []
    for sig in [SIGINT, SIGTERM, SIGHUP] {
      signal(sig, SIG_IGN)
      let src = DispatchSource.makeSignalSource(signal: sig, queue: .global())
      src.setEventHandler { kill(child, sig) }
      src.resume()
      relays.append(src)
    }
    var status: Int32 = 0
    while waitpid(child, &status, 0) == -1 && errno == EINTR {}
    exit((status & 0x7f) == 0 ? (status >> 8) & 0xff : 128 + (status & 0x7f))
  }
}

// 权限：未决定时由系统弹窗询问（等用户点选）；已拒绝直接报错，免得会话空跑没有画面
func authorize(_ media: AVMediaType) -> AVAuthorizationStatus {
  if AVCaptureDevice.authorizationStatus(for: media) == .notDetermined {
    let done = DispatchSemaphore(value: 0)
    AVCaptureDevice.requestAccess(for: media) { _ in done.signal() }
    _ = done.wait(timeout: .now() + 120)
  }
  return AVCaptureDevice.authorizationStatus(for: media)
}
if authorize(.video) != .authorized { fail("DENIED", 8) }

var addr = CMIOObjectPropertyAddress(
  mSelector: CMIOObjectPropertySelector(kCMIOHardwarePropertyAllowScreenCaptureDevices),
  mScope: CMIOObjectPropertyScope(kCMIOObjectPropertyScopeGlobal),
  mElement: CMIOObjectPropertyElement(kCMIOObjectPropertyElementMain))
var allow: UInt32 = 1
CMIOObjectSetPropertyData(CMIOObjectID(kCMIOObjectSystemObject), &addr, 0, nil, UInt32(MemoryLayout<UInt32>.size), &allow)

// 打开开关后屏幕设备异步出现；按设备名匹配，只有一台时直接用
var device: AVCaptureDevice?
let deadline = Date().addingTimeInterval(8)
while device == nil && Date() < deadline {
  let found = AVCaptureDevice.DiscoverySession(deviceTypes: [.external], mediaType: .muxed, position: .unspecified)
    .devices.filter { $0.modelID == "iOS Device" }
  device = found.first { $0.localizedName == name } ?? (found.count == 1 ? found[0] : nil)
  if device == nil { RunLoop.current.run(until: Date().addingTimeInterval(0.2)) }
}
guard let device else { fail("NODEVICE", 3) }

let session = AVCaptureSession()
do { session.addInput(try AVCaptureDeviceInput(device: device)) } catch { fail("INPUT \(error.localizedDescription)", 4) }

final class Shot: NSObject, AVCaptureVideoDataOutputSampleBufferDelegate {
  let queue = DispatchQueue(label: "shot")
  var latest: CVPixelBuffer?
  // 首帧到达后再等一小会儿取最新一帧，避开采集刚启动时的过渡画面；画面静止时设备只发一帧
  func captureOutput(_ output: AVCaptureOutput, didOutput sb: CMSampleBuffer, from c: AVCaptureConnection) {
    guard let px = CMSampleBufferGetImageBuffer(sb) else { return }
    if latest == nil { queue.asyncAfter(deadline: .now() + 0.5) { self.write() } }
    latest = px
  }
  func write() {
    guard let px = latest else { return }
    var image = CIImage(cvPixelBuffer: px)
    let clean = CVImageBufferGetCleanRect(px).integral
    if !clean.isEmpty && clean != image.extent { image = image.cropped(to: clean) }
    do {
      try CIContext().writePNGRepresentation(of: image, to: out, format: .RGBA8, colorSpace: CGColorSpace(name: CGColorSpace.sRGB)!)
      print("OK \(Int(image.extent.width))x\(Int(image.extent.height))")
      exit(0)
    } catch { fail("WRITE \(error.localizedDescription)", 5) }
  }
}

final class Recorder: NSObject, AVCaptureFileOutputRecordingDelegate {
  func fileOutput(_ output: AVCaptureFileOutput, didStartRecordingTo url: URL, from c: [AVCaptureConnection]) {
    print("STARTED")
  }
  func fileOutput(_ output: AVCaptureFileOutput, didFinishRecordingTo url: URL, from c: [AVCaptureConnection], error: Error?) {
    // 到达时长上限、设备拔出都会带 error，但文件仍然可用
    let size = (try? FileManager.default.attributesOfItem(atPath: url.path)[.size] as? Int) ?? 0
    print(size > 0 ? "DONE" : "ERR RECORD \(error?.localizedDescription ?? "empty")")
    exit(size > 0 ? 0 : 6)
  }
}

let shot = Shot(), recorder = Recorder()
let movie = AVCaptureMovieFileOutput()
var sources: [DispatchSourceSignal] = []
if mode == "shot" {
  let output = AVCaptureVideoDataOutput()
  output.videoSettings = [kCVPixelBufferPixelFormatTypeKey as String: kCVPixelFormatType_32BGRA]
  output.setSampleBufferDelegate(shot, queue: shot.queue)
  session.addOutput(output)
  session.startRunning()
  // 屏幕熄灭时设备不发画面
  DispatchQueue.main.asyncAfter(deadline: .now() + 8) { fail("NOFRAME", 7) }
} else {
  let limit = args.count > 4 ? Double(args[4]) ?? 1800 : 1800
  movie.maxRecordedDuration = CMTime(seconds: limit, preferredTimescale: 600)
  // 分段写入：进程被强杀时文件仍可播放，最多丢最后几秒
  movie.movieFragmentInterval = CMTime(seconds: 2, preferredTimescale: 600)
  session.addOutput(movie)
  session.startRunning()
  movie.startRecording(to: out, recordingDelegate: recorder)
  // isRecording 在主线程上读不可靠：停止一律调 stopRecording，等 didFinish 收尾，兜底 10 秒后退出
  func stop() {
    movie.stopRecording()
    DispatchQueue.main.asyncAfter(deadline: .now() + 10) { exit(0) }
  }
  for sig in [SIGINT, SIGTERM, SIGHUP] {
    signal(sig, SIG_IGN)
    let src = DispatchSource.makeSignalSource(signal: sig, queue: .main)
    src.setEventHandler(handler: stop)
    src.resume()
    sources.append(src)
  }
  NotificationCenter.default.addObserver(forName: AVCaptureDevice.wasDisconnectedNotification, object: device, queue: .main) { _ in stop() }
}
dispatchMain()
'''


SCREEN_PLIST = {
    "CFBundleIdentifier": "com.notchany.ios-screen",
    "CFBundleName": "NotchAny iOS Screen",
    "CFBundleDisplayName": "NotchAny iOS Screen",
    "NSCameraUsageDescription": "通过 USB 截取和录制 iPhone / iPad 屏幕（macOS 把 iOS 设备屏幕当作摄像头管理）。"
                                "Captures the screen of a USB-connected iPhone or iPad (macOS treats it as a camera).",
    "NSMicrophoneUsageDescription": "录屏时录入 iPhone / iPad 的声音。Records the iPhone or iPad sound in screen recordings.",
}


def screen_helper():
    plist = plistlib.dumps(SCREEN_PLIST)
    digest = hashlib.sha256(SCREEN_SWIFT.encode() + plist).hexdigest()[:12]
    path = os.path.join(STATE_DIR, "NotchScreen-" + digest)
    if os.access(path, os.X_OK):
        return path
    # 先确认装了开发者工具，避免 /usr/bin/swiftc 占位程序弹出安装窗；经 xcrun 调用才带上 macOS SDK
    if subprocess.run(["xcode-select", "-p"], capture_output=True).returncode != 0 or \
            subprocess.run(["xcrun", "--find", "swiftc"], capture_output=True).returncode != 0:
        sys.exit(T("ios_need_swift"))
    os.makedirs(STATE_DIR, exist_ok=True)
    src, info = path + ".swift", path + ".plist"
    with open(src, "w") as f:
        f.write(SCREEN_SWIFT)
    with open(info, "wb") as f:
        f.write(plist)
    # Info.plist 写进 __TEXT,__info_plist：命令行程序也能带摄像头用途说明；再用固定标识重签，系统设置里显示得清楚
    r = subprocess.run(["xcrun", "--sdk", "macosx", "swiftc", "-O", "-suppress-warnings", "-o", path + ".tmp", src,
                        "-Xlinker", "-sectcreate", "-Xlinker", "__TEXT", "-Xlinker", "__info_plist", "-Xlinker", info],
                       capture_output=True, text=True, timeout=300)
    if r.returncode == 0:
        r = subprocess.run(["codesign", "-s", "-", "-f", "-i", SCREEN_PLIST["CFBundleIdentifier"], path + ".tmp"],
                           capture_output=True, text=True, timeout=60)
    for p in (src, info):
        os.remove(p)
    if r.returncode != 0:
        err = (r.stderr.strip() or r.stdout.strip()).splitlines()
        sys.exit(T("ios_build_failed") + (" · " + err[-1] if err else ""))
    os.replace(path + ".tmp", path)
    for name in os.listdir(STATE_DIR):
        if name.startswith("NotchScreen-") and os.path.join(STATE_DIR, name) != path:
            os.remove(os.path.join(STATE_DIR, name))
    return path


def screen_error(code):
    if code.startswith("DENIED"):
        return T("ios_denied")
    if code.startswith("NODEVICE"):
        return T("ios_no_screen")
    if code.startswith("NOFRAME") or "Cannot Record" in code:
        return T("ios_no_frame")
    return code


def ios_screenshot(udid, label):
    helper = screen_helper()
    name = ios_device_name(udid) or label
    path = unique_path(f"{label} {time.strftime('%Y-%m-%d %H.%M.%S')}", ".png")
    tmp = os.path.join(os.environ.get("NOTCH_TEMP_DIR") or os.path.dirname(path), ".ios-screenshot.png")
    for attempt in range(2):
        try:
            r = subprocess.run([helper, "shot", name, tmp], capture_output=True, text=True, timeout=150)
        except subprocess.TimeoutExpired:
            sys.exit(T("err_shot_timeout", name=label))
        reply = r.stdout.strip().splitlines()[-1] if r.stdout.strip() else ""
        if reply.startswith("OK") and os.path.exists(tmp):
            shutil.move(tmp, path)
            return path
        # 上一次采集刚结束时设备还在重新枚举，稍等再试一次
        if attempt == 0 and reply.startswith("ERR NODEVICE"):
            time.sleep(2)
            continue
        break
    err = reply[4:] if reply.startswith("ERR ") else (r.stderr.strip().splitlines() or [""])[-1]
    sys.exit(T("err_shot_failed", name=label) + (" · " + screen_error(err) if err else ""))


def ios_recorder_alive(rec):
    try:
        os.kill(rec["pid"], 0)
    except (ProcessLookupError, PermissionError):
        return False
    out = subprocess.run(["ps", "-p", str(rec["pid"]), "-o", "stat=,comm="], capture_output=True, text=True).stdout
    return "NotchScreen" in out and not out.strip().startswith("Z")


def ios_start_recording(udid, label):
    if os.path.exists(rec_file(udid)):
        sys.exit(T("err_rec_busy", name=label))
    helper = screen_helper()
    name = ios_device_name(udid) or label
    try:
        minutes = float(os.environ.get("NOTCH_PARAM_RECORD_MAX_MINUTES") or 30)
    except ValueError:
        minutes = 30
    limit = max(60, int(minutes * 60))
    stamp = int(time.time() * 1000)
    movie = os.path.join(STATE_DIR, f"ios-rec-{stamp}.mov")
    log = movie[:-4] + ".log"
    for attempt in range(2):
        with open(log, "w") as f:
            # 用户点击（execute）发起，录屏进程在脚本退出后继续运行；停止时发 SIGINT 让它收尾
            proc = subprocess.Popen([helper, "record", name, movie, str(limit)],
                                    stdin=subprocess.DEVNULL, stdout=f, stderr=subprocess.STDOUT)
        # 首次使用要等用户在系统权限弹窗里点选
        deadline = time.time() + 150
        reply = ""
        while time.time() < deadline:
            with open(log) as f:
                lines = f.read().split()
            reply = next((l for l in lines if l in ("STARTED", "ERR")), "")
            if reply or proc.poll() is not None:
                break
            time.sleep(0.2)
        if reply == "STARTED" and proc.poll() is None:
            break
        if proc.poll() is None:
            proc.send_signal(signal.SIGINT)
            proc.wait(timeout=12)
        with open(log) as f:
            out = f.read().strip()
        err = next((l[4:] for l in reversed(out.splitlines()) if l.startswith("ERR ")), out.splitlines()[-1] if out else "")
        if attempt == 0 and err.startswith("NODEVICE"):
            time.sleep(2)
            continue
        for p in (movie, log):
            if os.path.exists(p):
                os.remove(p)
        sys.exit(T("err_rec_start", name=label) + (" · " + screen_error(err) if err else ""))
    rec = {"serial": udid, "label": label, "platform": "ios", "pid": proc.pid, "limit": limit,
           "remote": movie, "log": log, "started_at": int(time.time() * 1000)}
    with open(rec_file(udid), "w") as f:
        json.dump(rec, f)
    return rec


def ios_save_recording(rec, stop):
    serial, label = rec["serial"], rec["label"]
    if stop and ios_recorder_alive(rec):
        os.kill(rec["pid"], signal.SIGINT)
    deadline = time.time() + 15
    while ios_recorder_alive(rec):
        if time.time() > deadline:
            sys.exit(T("err_rec_stuck", name=label))
        time.sleep(0.3)
    if not os.path.exists(rec["remote"]) or os.path.getsize(rec["remote"]) == 0:
        for p in (rec["remote"], rec["log"], rec_file(serial)):
            if os.path.exists(p):
                os.remove(p)
        sys.exit(T("err_rec_gone", name=label))
    stamp = time.strftime("%Y-%m-%d %H.%M.%S", time.localtime(rec["started_at"] / 1000))
    path = unique_path(f"{label} {stamp}", ".mov")
    shutil.move(rec["remote"], path)
    if os.path.exists(rec["log"]):
        os.remove(rec["log"])
    os.remove(rec_file(serial))
    return path


def emit(state, notes, **kw):
    if notes:
        kw["notification"] = notes
    notch_result(widget=state, **kw)


event = os.environ.get("NOTCH_WIDGET_EVENT", "")
payload = json.loads(os.environ.get("NOTCH_WIDGET_PAYLOAD") or "null") or {}
serial = payload.get("serial")
label = payload.get("name") or serial
adb = find_adb()
# 通知里的「停止并保存」只带序列号，平台从录屏记录里取
ios = bool(serial) and (payload.get("platform") or next(
    (r.get("platform") for r in load_recordings() if r["serial"] == serial), None)) == "ios"
DEVICE_EVENTS = ("screenshot", "record-start", "record-stop", "detail", "detail-live", "clip-set", "clip-get")

if event in ("notification-launch", "notification-poll"):
    # 后台通知引擎：没有录屏时什么都不做，不去碰 adb / usbmuxd
    if not load_recordings():
        sys.exit(0)
    connected = set()
    if adb and server_running():
        connected = {d["serial"] for d in list_devices(adb) if d["state"] == "device"}
    notes = reconcile(adb, connected)[1]
    if notes:
        notch_result(notification=notes)
elif event == "start-server" and adb:
    subprocess.run([adb, "start-server"], capture_output=True, timeout=20)
    state, notes = snapshot(adb)
    emit(state, notes, summary=T("adb_started") if state["adb"] == "ok" else T("adb_start_failed"))
elif ios and event == "screenshot":
    path = ios_screenshot(serial, label)
    state, notes = snapshot(adb)
    extra = {"copy_image": path} if os.environ.get("NOTCH_PARAM_COPY_IMAGE", "1") == "1" else {}
    emit(state, notes, summary=T("shot_saved", name=label), details=path, outputs=[path], **extra)
elif ios and event == "record-start":
    ios_start_recording(serial, label)
    state, notes = snapshot(adb)
    emit(state, notes, summary=T("rec_started", name=label))
elif ios and event == "detail":
    sections, live = ios_detail(serial, label)
    notch_result(widget={"status": "detail", "serial": serial, "sections": sections, "live": live})
elif ios and event == "detail-live":
    notch_result(widget={"status": "live", "serial": serial, "live": ios_detail(serial, label, live_only=True)[1]})
elif not ios and event in DEVICE_EVENTS and serial and adb_state(adb) != "ok":
    # 不在后台静默拉起 adb 服务：交给用户点「启动」(execute) 来起常驻进程
    sys.exit(T("server_stopped") if adb else T("no_adb"))
elif event == "screenshot" and serial:
    path = take_screenshot(adb, serial, label)
    state, notes = snapshot(adb)
    extra = {"copy_image": path} if os.environ.get("NOTCH_PARAM_COPY_IMAGE", "1") == "1" else {}
    emit(state, notes, summary=T("shot_saved", name=label), details=path, outputs=[path], **extra)
elif event == "record-start" and serial:
    start_recording(adb, serial, label)
    state, notes = snapshot(adb)
    emit(state, notes, summary=T("rec_started", name=label))
elif event == "record-stop" and serial:
    fd = lock(serial, block=True)
    try:
        rec = next((r for r in load_recordings() if r["serial"] == serial), None)
        path = save_recording(adb, rec, stop=True) if rec else None
    finally:
        fd.close()
    state, notes = snapshot(adb)
    notes.insert(0, {"end": "rec-" + serial})
    if path:
        if payload.get("via") == "notification":
            notes.append(saved_note(rec, path))
        emit(state, notes, summary=T("rec_saved_summary", name=rec["label"]), details=path, outputs=[path])
    else:
        emit(state, notes, summary=T("rec_none", name=label))
elif event == "detail" and serial:
    with ThreadPoolExecutor(max_workers=2) as pool:
        static, live = pool.submit(collect_static, adb, serial), pool.submit(collect_live, adb, serial)
        notch_result(widget={"status": "detail", "serial": serial, "sections": static.result(), "live": live.result()})
elif event == "detail-live" and serial:
    notch_result(widget={"status": "live", "serial": serial, "live": collect_live(adb, serial)})
elif event == "clip-set" and serial:
    clip_helper(adb, serial, label, "set", base64.b64encode(payload.get("text", "").encode()).decode())
    notch_result(summary=T("clip_sent", name=label), widget={"status": "clip", "serial": serial, "result": "sent"})
elif event == "clip-get" and serial:
    reply = clip_helper(adb, serial, label, "get")
    if reply.startswith("OK"):
        text = base64.b64decode(reply[3:]).decode("utf-8", errors="replace")
        notch_result(summary=T("clip_pulled", name=label), copy_text=text,
                     widget={"status": "clip", "serial": serial, "result": "pulled", "text": text})
    else:
        key = {"LOCKED": "clip_locked", "NONTEXT": "clip_nontext"}.get(reply, "clip_empty")
        notch_result(summary=T(key, name=label), widget={"status": "clip", "serial": serial, "result": reply.lower()})
elif event == "copy" and payload.get("text"):
    notch_result(summary=T("copied", what=payload.get("what", "")), copy_text=payload["text"])
else:
    state, notes = snapshot(adb)
    emit(state, notes)

